import {Button, onButtonClicked} from "@/cards/button";

register((r) => {
  onButtonClicked(r, (state, {id}) => {
    if (id === "save") {
      state.isSaving = true;
    }
  });
});

registerCard("myApp/saveButton", Button({
  id:    "save",
  label: "Save",
  opts:  {variant: "default"},
}));
