import {registerCard} from "@pihanga2/core";
import {FlexGrid} from "@/cards/flexGrid";

registerCard("myApp/shell", FlexGrid({
  height: "100vh",
  cards: {
    header: "myApp/header",
    nav:    "myApp/sidebar",
    main:   "myApp/content",
    footer: "myApp/statusBar",
  },
  template: {
    area: [
      ["header", "header"],
      ["nav",    "main"  ],
      ["footer", "footer"],
    ],
    rows:    ["56px", "1fr", "32px"],
    columns: ["240px", "1fr"],
    gap:     "0",
  },
}));
